import { assessImagery, captureLabel, nativeZoomLimit } from './imagery-policy.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const animalNames=['Bird','Cat','Dog','Horse','Sheep','Cow','Elephant','Bear','Zebra','Giraffe'];
const organismGroups=['Land Mammals','Aquatic/Marine Animals','Reptilian Creatures','Humans','Unclassified Wildlife'];
const isWildlife=d=>d.category==='Wildlife'||['animal-model','overhead-model'].includes(d.origin)||(d.humanOrganismGroup&&d.humanOrganismGroup!=='Humans');
const organismGroup=d=>d.humanOrganismGroup||d.organismGroup||(['person-model','aerial-person-model'].includes(d.origin)?'Humans':d.origin==='animal-model'?(d.type==='Bird'?'Unclassified Wildlife':'Land Mammals'):null);
