const colors={'Structure candidate':'#f0cb79','Mapped heritage':'#76cddd','Unclassified wildlife':'#f3c76b',Car:'#b0ee84',Truck:'#79c2ec',Boat:'#edb674',Airplane:'#bd9ae9',Bus:'#e58aaa',Train:'#7ed5c7',Building:'#65d8d1','Unknown feature':'#f3c76b',Person:'#8daaf4',Agriculture:'#a6c96c',...Object.fromEntries(animalNames.map(name=>[name,'#e9a7cc']))};
