function schedulePoll(){clearTimeout(pollTimer);if(!scan||terminal.has(scan.status))return;const id=scan.id;pollTimer=setTimeout(async()=>{try{const data=await api(`/api/scans/${id}`);if(scan?.id!==id)return;applyScan(data.scan)}catch(e){notice(e.message,true)}schedulePoll()},1800)}
async function openScan(id){clearTimeout(pollTimer);try{const data=await api(`/api/scans/${encodeURIComponent(id)}`);applyScan(data.scan);schedulePoll();$('#modal').close()}catch(e){toast(e.message)}}
async function submitScan(c){if(busy||submitting)return;if(c.source==='aerial'&&!c.baselineId){notice('High-detail imagery unavailable for this location. Import a licensed aerial baseline first, or select Context imagery.',true);return;}submitting=true;$('#run').disabled=true;$('#run').innerHTML='<span>⌖</span> Resolving location…';try{const data=await api('/api/scans',{method:'POST',body:JSON.stringify(c)});$('#modal').close();applyScan(data.scan);schedulePoll();toast(c.parentScanId?'Close-up scan queued':'Scan queued for the vision engine')}catch(e){notice(e.message,true);toast(e.message);busyState(false)}finally{submitting=false}}
