$('#cancel').onclick=async()=>{if(!scan)return;$('#cancel').disabled=true;try{const data=await api(`/api/scans/${scan.id}/cancel`,{method:'POST',body:'{}'});applyScan(data.scan);clearTimeout(pollTimer)}catch(e){toast(e.message)}finally{$('#cancel').disabled=false}};
function normalizedPoint(e){const r=$('#world').getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
function coordinates(p){const[left,bottom,right,top]=scan.imagery.bounds3857,r=6378137,x=left+p.x*(right-left),y=top-p.y*(top-bottom);return{latitude:(2*Math.atan(Math.exp(y/r))-Math.PI/2)*180/Math.PI,longitude:x/r*180/Math.PI}}
function setMapMode(mode){mapMode=mode;$('#map').dataset.mode=mode;$('#mark-feature').classList.toggle('selected',mode==='mark');$('#inspect-location').classList.toggle('selected',mode==='inspect');$('#draw-region').hidden=true;if(mode!=='pan')toast(mode==='mark'?'Drag a rectangle around any feature. Tap to mark a small region.':'Click the location to acquire a close-up scan.')}
function inspectionConfig(lat,lon,radiusMeters){return{...scan.configuration,latitude:lat,longitude:lon,radiusKm:radiusMeters/1000,radiusUnit:'km',classes:[...new Set([...normalizedTargets(scan.configuration.classes),'Building','Unknown feature','Archaeology'])],zoom:20,parentScanId:scan.id}}
function inspectAt(lat,lon,title='Inspect this location',wildlife=false,living=false,agriculture=false){
 modal(title,`<p class="green">ACQUIRE A SMALLER AREA · ANALYZE MORE DETAIL</p><p>Center: <code>${lat.toFixed(7)}, ${lon.toFixed(7)}</code></p><label class="analysis-label">Close-up radius<select id="inspection-radius"><option value="50">50 m</option><option value="100" selected>100 m</option><option value="250">250 m</option></select></label><p>Context requests acquire a smaller area. Imported aerial scans reuse their licensed baseline and must stay inside its bounds. Detailed detection runs only on qualifying aerial imagery. Extra pixels cannot recover detail absent from the source imagery. The overview remains in scan history.</p><button class="primary" id="start-inspection" ${!health?.worker.online?'disabled':''}>Acquire close-up & rescan ↗</button>`);$('#start-inspection').onclick=()=>{const c=inspectionConfig(lat,lon,+$('#inspection-radius').value);if((wildlife||living)&&!c.classes.includes('Living Organisms'))c.classes.push('Living Organisms');if(c.classes.includes('Living Organisms')){c.organismCategories=savedGroups(c);c.useAerialWildlife=c.useAerialWildlife!==false;delete c.wildlifeSpecies}if(agriculture&&!c.classes.includes('Agriculture'))c.classes.push('Agriculture');submitScan(c)};
}
function drawCrop(canvas,d){const image=$('#world>img');if(!canvas||!image.complete||!image.naturalWidth)return;const[x1,y1,x2,y2]=d.bboxNormalized,pad=Math.max(x2-x1,y2-y1)*.35+.003,left=Math.max(0,x1-pad),top=Math.max(0,y1-pad),right=Math.min(1,x2+pad),bottom=Math.min(1,y2+pad);canvas.width=900;canvas.height=Math.min(600,Math.max(260,900*(bottom-top)/(right-left)));const ctx=canvas.getContext('2d');ctx.fillStyle='#0c1215';ctx.fillRect(0,0,canvas.width,canvas.height);const scale=Math.min(canvas.width/((right-left)*image.naturalWidth),canvas.height/((bottom-top)*image.naturalHeight)),w=(right-left)*image.naturalWidth*scale,h=(bottom-top)*image.naturalHeight*scale;ctx.imageSmoothingEnabled=false;ctx.drawImage(image,left*image.naturalWidth,top*image.naturalHeight,(right-left)*image.naturalWidth,(bottom-top)*image.naturalHeight,(canvas.width-w)/2,(canvas.height-h)/2,w,h);ctx.strokeStyle=colors[d.type]||'#f3c76b';ctx.lineWidth=2;ctx.strokeRect((canvas.width-w)/2+(x1-left)*image.naturalWidth*scale,(canvas.height-h)/2+(y1-top)*image.naturalHeight*scale,(x2-x1)*image.naturalWidth*scale,(y2-y1)*image.naturalHeight*scale)}
function detail(id){
 const d=detections.find(d=>d.id===id);if(!d)return;selectedId=id;render();const dimensions=d.dimensionsMeters;
 modal(`${featureTitle(d)} / ${d.id.slice(0,16)}`,`<p class="green">${escapeHtml(evidence(d).toUpperCase())} · HUMAN ANALYSIS REQUIRED</p><canvas id="detail-canvas" class="feature-crop" aria-label="Cropped satellite view of selected feature"></canvas><div class="feature-meta"><span>Classification: <b>${confidenceText(d)}</b></span><span>${dimensions?`Approx. ${dimensions.width.toFixed(1)} × ${dimensions.height.toFixed(1)} m`:'Dimensions unavailable'}</span></div><p>${escapeHtml(d.description||'Machine estimate; human review required.')}</p>${isLiving(d)?`<p>Original model suggestion: ${escapeHtml(d.type)}. Category: ${escapeHtml(organismGroup(d)||'Unclassified')}.</p>`:''}${flagMarkup(d)}${d.flagBasis?`<p>${escapeHtml(d.flagBasis)}</p>`:''}${d.localizationScore!=null?`<p>Aerial localization activation: ${d.localizationScore.toFixed(3)} (not a probability). Review window, not a body outline.</p>`:''}${isLiving(d)?'<p class="wildlife-detail-note">Possible organism only. Model suggestions and image sampling do not establish the species or animal presence. Historical imagery cannot show where an animal is now.</p>':''}<p>Coordinates: <code>${d.latitude.toFixed(7)}, ${d.longitude.toFixed(7)}</code><br>Evidence: ${escapeHtml(evidence(d))} · ${escapeHtml(d.tile)}</p>${inspectionMarkup(d.latitude,d.longitude)}<button class="secondary inspect-feature" id="inspect-feature">⌕ Acquire close-up & rescan</button><div class="assessment-fields"><label class="analysis-label">Your label<input id="feature-label" maxlength="100" value="${escapeHtml(d.label||'')}" placeholder="e.g. Oval roof — purpose unknown"></label><label class="analysis-label">Assessment<select id="feature-assessment">${['Unidentified','Possible structure/remnant','Mapped historic feature','Model suggestion','Likely man-made','Likely natural','Confirmed structure','Possible animal','Confirmed animal','Possible wildlife','Probable wildlife','Possible organism','Possible person','Confirmed person','Possible agriculture','Confirmed agriculture','Dismissed'].map(v=>`<option ${v===(d.assessment||'Model suggestion')?'selected':''}>${v}</option>`).join('')}</select></label><label class="analysis-label">Human organism category<select id="human-organism"><option value="">Leave unclassified</option>${organismGroups.map(g=>`<option ${g===(d.humanOrganismGroup||d.organismGroup)?'selected':''}>${g}</option>`).join('')}</select></label><label class="analysis-label">Analysis notes<textarea id="feature-notes" maxlength="2000" rows="3" placeholder="Record observations and evidence; keep uncertain interpretations labeled.">${escapeHtml(d.notes||'')}</textarea></label></div><div class="training-crop-action"><p>Review the native crop before adding a training example. Use <b>Mark feature</b> to draw tightly around a missed person or structure; include negative examples too. Saving examples does not retrain the model automatically.</p><button class="secondary" id="save-training-example">Cut & label training example ↗</button></div><div class="analysis-actions"><button class="primary" id="save-assessment">Save assessment</button><button class="secondary" id="review">${d.reviewed?'Reopen review':'Mark reviewed'}</button></div>`);
 drawCrop($('#detail-canvas'),d);$('#save-training-example').onclick=()=>labelExample(d);loadStreetLevel(scan.id,d.id);$('#inspect-feature').disabled=!health?.worker.online;$('#inspect-feature').onclick=()=>inspectAt(d.latitude,d.longitude,'Inspect '+featureTitle(d),isWildlife(d),isLiving(d)&&!isWildlife(d),isAgriculture(d));const scanId=scan.id;
 async function save(reviewed){$('#review').disabled=true;$('#save-assessment').disabled=true;try{const data=await api(`/api/scans/${scanId}/review`,{method:'PATCH',body:JSON.stringify({detectionId:id,reviewed,label:$('#feature-label').value,assessment:$('#feature-assessment').value,notes:$('#feature-notes').value,humanOrganismGroup:$('#human-organism').value})});applyScan(data.scan);$('#modal').close();toast('Assessment saved')}catch(e){toast(e.message);$('#review').disabled=false;$('#save-assessment').disabled=false}}
 $('#review').onclick=()=>save(!d.reviewed);$('#save-assessment').onclick=()=>save(true);
}
function markRegion(bbox){
 const center={x:(bbox[0]+bbox[2])/2,y:(bbox[1]+bbox[3])/2},point=coordinates(center),d={bboxNormalized:bbox,type:'Unknown feature'};modal('Mark an unknown feature',`<p class="green">USER-MARKED REGION · UNIDENTIFIED</p><canvas id="mark-canvas" class="feature-crop" aria-label="Selected region"></canvas><p><code>${point.latitude.toFixed(7)}, ${point.longitude.toFixed(7)}</code></p><label class="analysis-label">Region category<select id="mark-category"><option value="General">Unclassified feature</option><option value="Living Organisms">Possible living organism · unclassified</option><option value="Agriculture">Possible agriculture · crop unknown</option></select></label><label class="analysis-label">Organism category (optional)<select id="mark-organism"><option value="">Unclassified</option>${organismGroups.map(g=>`<option>${g}</option>`).join('')}</select></label><label class="analysis-label">Label<input id="mark-label" maxlength="100" placeholder="e.g. Triangular roof-like feature"></label><label class="analysis-label">Observations<textarea id="mark-notes" maxlength="2000" rows="3" placeholder="Describe what you see. The feature remains unclassified until reviewed."></textarea></label><button class="primary" id="save-mark">Save marked feature</button>`);drawCrop($('#mark-canvas'),d);$('#mark-category').value=scan.configuration.classes.includes('Wildlife')?'Living Organisms':scan.configuration.classes.includes('Living Organisms')?'Living Organisms':scan.configuration.classes.includes('Agriculture')?'Agriculture':'General';const scanId=scan.id;$('#save-mark').onclick=async()=>{$('#save-mark').disabled=true;try{const data=await api(`/api/scans/${scanId}/annotations`,{method:'POST',body:JSON.stringify({bboxNormalized:bbox,label:$('#mark-label').value,notes:$('#mark-notes').value,category:$('#mark-organism').value?'Living Organisms':$('#mark-category').value,organismGroup:$('#mark-organism').value})});applyScan(data.scan);setMapMode('pan');detail(data.detectionId);toast('Marked feature saved in this scan and report')}catch(e){toast(e.message);$('#save-mark').disabled=false}};
}
async function showHistory(){modal('Scan history','<p>Loading saved scans…</p>');try{const data=await api('/api/scans');$('#modal-body').innerHTML=data.scans.length?data.scans.map(h=>`<button class="history-item" data-scan="${h.id}"><span><b>${h.configuration.parentScanId?'⌕ Close-up · ':''}${escapeHtml(h.location?.label||`${h.configuration.latitude}, ${h.configuration.longitude}`)}</b><br>${h.configuration.radiusKm<.5?`${h.configuration.radiusKm*1000} m`:`${h.configuration.radiusKm} km`} radius · ${escapeHtml(new Date(h.createdAt).toLocaleString())}</span><span class="green">${h.count} findings<br>${escapeHtml(h.status.toUpperCase())}</span></button>`).join(''):'<p>No scans yet.</p>';$$('[data-scan]').forEach(b=>b.onclick=()=>openScan(b.dataset.scan))}catch(e){$('#modal-body').textContent=e.message}}
async function downloadReport(){if(scan?.status!=='completed')return;try{const response=await fetch(`/api/scans/${scan.id}/report`);if(!response.ok)throw Error('Report download failed.');downloadBlob(await response.blob(),`avie-${scan.id}.json`);toast('Report downloaded with assessments and marked regions')}catch(e){toast(e.message)}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportMarkedImage(){const image=$('#world>img');if(!image.complete||$('#map').classList.contains('imagery-pending')){toast('Wait for the source image to load.');return}const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);ctx.font='16px monospace';ctx.lineWidth=2;for(const d of detections){const[x1,y1,x2,y2]=d.bboxNormalized;ctx.strokeStyle=colors[d.type]||'#fff';ctx.fillStyle=ctx.strokeStyle;ctx.strokeRect(x1*canvas.width,y1*canvas.height,(x2-x1)*canvas.width,(y2-y1)*canvas.height);ctx.fillText(featureTitle(d),x1*canvas.width,Math.max(18,y1*canvas.height-5))}canvas.toBlob(blob=>downloadBlob(blob,`avie-markings-${scan.id}.png`),'image/png')}
function showReport(){if(scan?.status!=='completed'){toast('Complete a scan to generate a report.');return}const info=scan.imagery||{},assessment=assessImagery(info);modal('Intelligence report',`<p class="green">${assessment.eligible?'QUALIFIED AERIAL BASELINE':'CONTEXT ONLY · IMAGE DETECTION NOT ASSESSED'}</p><h3>${detections.length} saved findings · ${detections.filter(d=>d.reviewed).length} reviewed</h3><p>${escapeHtml(findingsSummary())}<br>Location: ${escapeHtml(scan.location?.label||'Place name unavailable')}<br>Center: ${scan.configuration.latitude}, ${scan.configuration.longitude}<br>Radius: ${scan.configuration.radiusKm} km<br>Source: ${escapeHtml(info.provider||'Unverified')}<br>Native capture resolution: ${escapeHtml(info.nativeGsdCm??'Unknown')} cm/pixel<br>Delivered pixel spacing: ${escapeHtml(info.groundResolutionMeters??'Unknown')} m/pixel<br><b>Image captured: ${escapeHtml(captureLabel(info))}</b><br>Image acquired/imported: ${escapeHtml(info.acquiredAt||'Unavailable')}<br><b>Analysis performed: ${escapeHtml(scan.analysisAt||scan.completedAt||'Unavailable')}</b></p><p>Findings describe the captured image, not current conditions. Image age is unrestricted. Minimum native resolution: 5 cm/pixel; preferably 2–3 cm. A blocked detection is not evidence of absence.</p>${!assessment.eligible?`<p>High-detail imagery unavailable for this location.</p><ul>${assessment.limitations.map(n=>`<li>${escapeHtml(n)}</li>`).join('')}</ul>`:`<img class="report-preview" src="${asset('confidence.png')}" alt="Original automatic findings by class">`}<p>Licence reference: ${escapeHtml(info.licenseReference||'Unverified')}. AI analysis: ${info.analysisPermitted===true?'permitted':'unverified'}. App display: ${info.displayPermitted===true?'permitted':'unverified'}.</p><ul>${(scan.notices||[]).map(n=>`<li>${escapeHtml(n)}</li>`).join('')}</ul><div class="report-links"><a href="${asset('imagery.jpg')}" target="_blank" rel="noopener">Open source image ↗</a><button id="marked-image" class="secondary">Export all current markings ↓</button></div><button class="primary" id="download">Download JSON report ↓</button>`);$('#download').onclick=downloadReport;$('#marked-image').onclick=exportMarkedImage}
async function checkHealth(){try{health=await api('/api/health');const upgrade=health.worker.online&&health.worker.analysisVersion<7;$('.online').innerHTML=`<i></i> ${upgrade?'WORKER UPDATE NEEDED':health.worker.online?'ENGINE ONLINE':'WORKER OFFLINE'}`;$('#engine-status').innerHTML=health.worker.online?'<i class="tiny-dot"></i> Vision engine connected <span>· Historical imagery</span>':'<span>Worker offline · Saved findings available</span>';if(upgrade)$('#engine-status').textContent='Server worker update required · aerial imports need v7';$('#engine-status').classList.toggle('offline',!health.worker.online||upgrade);$('#inspect-location').disabled=scan?.status!=='completed'||!health.worker.online}catch(e){$('.online').textContent='CONNECTION UNAVAILABLE';$('#engine-status').textContent='Cannot connect to the service';if(!scan)notice(e.message,true)}}
function about(){modal('Engine & analysis guide',`<p>AVIE — Anomaly Vision Intelligence Engine</p><h3>Location and street-level inspection</h3><p>City/locality, state or region, and country are looked up at the scan center using OpenStreetMap/Nominatim. The scan radius may cross administrative boundaries. Rural places may have no city, and unavailable names are never guessed. Tibet is displayed as Tibet while the provider's original region label is retained in the report.</p><p>OpenStreetMap links open the actual selected coordinates. Panoramax is checked for nearby ground photos within 150 m; a verified-photo button appears only when one is found. Google Street View and Mapillary links let you check those providers separately; their coverage is not pre-verified. Nearby photos may not show the selected object or match the satellite capture date.</p><h3>Archaeology and small humans</h3><p>Archaeology / structure remnants searches multiscale stone-like contrast clusters in the image. This is an exploratory geometry proposal, not a trained archaeology classifier, and cannot date a site or prove human origin. Known historic features from OpenStreetMap appear as separate mapped evidence; naming Stonehenge from map data is not a new discovery. Buried features, subtle crop marks, earthworks, and natural lookalikes remain challenging.</p><p>Humans can use a dedicated VisDrone-trained aerial detector on overlapping 320 px crops magnified to 960 px for inference. Extra input pixels do not recover real image detail. Confidence is separate from the general object threshold. Drone validation does not establish satellite accuracy. Mark missed people, review their native crops, save positive and negative examples, and export the labelled dataset for custom training. Nothing learns automatically from an unreviewed box. Model source: <a href="https://huggingface.co/mshamrai/yolov8s-visdrone" target="_blank" rel="noopener">YOLOv8s-VisDrone</a>; model card OpenRAIL; dataset research terms and Ultralytics license apply. Imagery licensing must permit any intended training/reuse.</p><h3>Evidence sources</h3><p><b>Living Organisms:</b> choose Land Mammals, Aquatic/Marine Animals, Reptilian Creatures, Humans, or Unclassified Wildlife. Individual species remain model evidence rather than a selection menu.</p><p><b>Active aerial model:</b> <a href="https://github.com/microsoft/MegaDetector-Overhead" target="_blank" rel="noopener">Microsoft OWL-C</a> localizes possible animals from above. It does not identify species. Weights are CC BY-NC-SA 4.0 (noncommercial/sharealike); code is MIT. AVIE satellite accuracy improvement has not been measured. General animal and aerial human detection remain experimental on satellite imagery.</p><p><b>Possible:</b> a single model candidate. <b>Probable:</b> spatial agreement between general animal detection and the independent aerial locator. Human assessments are saved separately. These flags are review priorities, not calibrated biological probabilities.</p><p><b>Research datasets:</b> <a href="https://github.com/xiaohuicui/WAID" target="_blank" rel="noopener">WAID aerial wildlife</a>, <a href="https://www.bas.ac.uk/data/our-data/publication/whales-from-space-dataset-an-annotated-satellite-image-dataset-of-whales-for-training-machine-learning-models/" target="_blank" rel="noopener">Whales from Space</a>, and <a href="https://datadryad.org/dataset/doi%3A10.5061/dryad.s4mw6m98n" target="_blank" rel="noopener">UAV crocodile imagery</a> offer examples for future specialist training. They have not been trained into this app. Marine and reptile categories currently support manual marking/review only; no automatic specialist coverage is implied.</p><h3>Transport, organisms, and agriculture</h3><p><b>Road Transport:</b> cars, trucks, and buses; Train and Boat remain separate targets. Aircraft are not a new scan target.<br><b>Living Organisms:</b> searches selected organism categories where a detector is available. This is experimental overhead detection, not identity recognition or live tracking. It does not classify all plants.<br><b>Agriculture:</b> mapped farmland, vineyards, orchards, greenhouses, allotments, and meadow/grassland from OpenStreetMap. Crop tags such as wheat or corn are shown only if the map supplies them. Crop identity is not inferred from field shape or color. Map data may be incomplete, stale, or unavailable, and may differ from the satellite image date. Land-use data: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener" style="color:var(--green)">© OpenStreetMap contributors (ODbL)</a>.</p><h3>Trying wildlife scans</h3><p>Choose Living Organisms and the categories of interest. Import a qualifying licensed aerial baseline before running people or animal detection. Use a scan radius fully contained in that image. Changing zoom or model confidence cannot substitute for native source detail. Lower thresholds increase false positives. Large animals in open terrain offer the best chance, while trees, shadows, small bodies, and limited native imagery detail can prevent detection. No detections does not establish that animals are absent. For reliable wildlife surveys, use suitable high-resolution aerial or drone imagery and a model trained and validated on the target species and viewing conditions.</p><p><b>Vehicle model:</b> general-purpose YOLOv8 for six vehicle classes.<br><b>Satellite building model:</b> roof/building footprints from <a href="https://huggingface.co/keremberke/yolov8n-building-segmentation" target="_blank" rel="noopener" style="color:var(--green)">a satellite-trained segmentation model</a>. It does not identify a building's purpose.<br><b>Unknown visual proposals:</b> compact bright regions selected by geometry, with no classification probability. Natural features may be included.</p><h3>Investigate anything</h3><p>Use <b>Mark feature</b> to draw around any region the detectors missed. Use <b>Inspect location</b> or a finding's close-up action to acquire a smaller area at a finer requested pixel spacing. Save labels, assessments, and notes in the finding panel. A manually marked region can be categorized as possible wildlife without inventing a species or model probability. These remain human assessments, separate from the model's class.</p><h3>Resolution and coverage</h3><p>Zoom stops at one display pixel per source pixel. Aerial baselines require native 5 cm/pixel or better, preferably 2–3 cm, with verified analysis and display rights. Historical capture age is unrestricted. Context imagery does not qualify for detailed detection. Close-up scans request new imagery, but the provider's native imagery still sets the real detail limit. Large scans are capped at 4096 × 4096 pixels; inspect small areas for detail.</p><p>No detector marks or identifies everything. Roads, subtle terrain changes, dark features, and unusual structures can be missed. Capture timestamps retain provider precision; missing dates or times are labelled unavailable. Coordinates and dimensions are estimates. The Python worker must remain running for new scans.</p><p>Radius units are explicit. 2 miles is about 3.22 km.</p>`)}
$$('#radius,#confidence,input[name=target],input[name=organism],#aerial-wildlife').forEach(e=>e.addEventListener('input',updateInputs));$('#radius-unit').onchange=()=>{const km=+$('#radius').value*($('#radius').dataset.unit==='mi'?1.609344:1),unit=$('#radius-unit').value;radiusBounds(unit);$('#radius').value=km/(unit==='mi'?1.609344:1);$('#radius').dataset.unit=unit;updateInputs()};
$('#select-all').onclick=()=>{$$('input[name=target],input[name=organism]').forEach(e=>e.checked=true);$('#aerial-people').checked=true;$('#aerial-wildlife').checked=true;updateInputs()};
$('#collapse').onclick=()=>{let body=$('#form-body'),collapsed=body.hidden;body.hidden=!collapsed;body.style.display=collapsed?'':'none';$('#collapse').textContent=collapsed?'⌃':'⌄';$('#collapse').setAttribute('aria-expanded',String(collapsed))};$('#filter').onchange=render;$('#all').onclick=()=>{showAll=!showAll;render()};
function changeZoom(next,point=null){const img=$('#world>img'),map=$('#map');const limit=img.naturalWidth?nativeZoomLimit(img.naturalWidth,img.naturalHeight,map.clientWidth,map.clientHeight):1;if(next>limit)toast('Native pixel limit reached. More zoom would only enlarge pixels.');next=Math.max(.25,Math.min(limit,next));if(point){const map=$('#map').getBoundingClientRect(),dx=point.x-map.left-map.width/2,dy=point.y-map.top-map.height/2,factor=next/zoom;panX=dx-(dx-panX)*factor;panY=dy-(dy-panY)*factor}zoom=next;fitImage()}
$('#zoom-in').onclick=()=>changeZoom(zoom*1.5);$('#zoom-out').onclick=()=>changeZoom(zoom/1.5);$('#recenter').onclick=()=>{zoom=1;panX=0;panY=0;fitImage()};$('#expand').onclick=()=>{$('.map-panel').classList.toggle('expanded');fitImage()};$('#close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
$('#mark-feature').onclick=()=>setMapMode(mapMode==='mark'?'pan':'mark');$('#inspect-location').onclick=()=>setMapMode(mapMode==='inspect'?'pan':'inspect');$('#toggle-labels').onclick=()=>{labelsVisible=!labelsVisible;$('#map').classList.toggle('hide-labels',!labelsVisible);$('#toggle-labels').textContent=labelsVisible?'Smart labels':'Labels off';$('#toggle-labels').setAttribute('aria-pressed',String(labelsVisible))};$('#parent-overview').onclick=()=>openScan(scan.configuration.parentScanId);$('#reanalyze').onclick=()=>{$$('input[name=target]').filter(e=>['Building','Unknown feature','Archaeology'].includes(e.value)).forEach(e=>e.checked=true);$('#detail-zoom').value=String(Math.max(19,+$('#detail-zoom').value));$('#aerial-people').checked=true;updateInputs();$('#scan-form').requestSubmit()};
$('#map').addEventListener('wheel',e=>{if(!scan||busy)return;e.preventDefault();changeZoom(zoom*(e.deltaY<0?1.15:1/1.15),{x:e.clientX,y:e.clientY})},{passive:false});
$('#map').addEventListener('pointerdown',e=>{if(e.target.closest('button')&&mapMode==='pan')return;if(e.target.closest('.zoom'))return;if($('#map').classList.contains('imagery-pending'))return;const point=normalizedPoint(e);if(mapMode!=='pan'&&(point.x<0||point.x>1||point.y<0||point.y>1))return;drag={x:e.clientX,y:e.clientY,startX:panX,startY:panY,point};wasDragged=false;$('#map').setPointerCapture(e.pointerId)});
$('#map').addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)wasDragged=true;if(mapMode==='pan'){panX=drag.startX+dx;panY=drag.startY+dy;fitImage()}else if(mapMode==='mark'){const p=normalizedPoint(e),x1=Math.max(0,Math.min(drag.point.x,p.x)),y1=Math.max(0,Math.min(drag.point.y,p.y)),x2=Math.min(1,Math.max(drag.point.x,p.x)),y2=Math.min(1,Math.max(drag.point.y,p.y));$('#draw-region').hidden=false;Object.assign($('#draw-region').style,{left:x1*100+'%',top:y1*100+'%',width:(x2-x1)*100+'%',height:(y2-y1)*100+'%'})}});
$('#map').addEventListener('pointerup',e=>{if(!drag)return;const started=drag;drag=null;const p=normalizedPoint(e);$('#draw-region').hidden=true;if(mapMode==='inspect'){setMapMode('pan');const c=coordinates(started.point);inspectAt(c.latitude,c.longitude)}else if(mapMode==='mark'){let x1=Math.max(0,Math.min(started.point.x,p.x)),y1=Math.max(0,Math.min(started.point.y,p.y)),x2=Math.min(1,Math.max(started.point.x,p.x)),y2=Math.min(1,Math.max(started.point.y,p.y));if(!wasDragged){const r=$('#world').getBoundingClientRect(),pad=14/Math.max(1,r.width);x1=Math.max(0,p.x-pad);x2=Math.min(1,p.x+pad);y1=Math.max(0,p.y-pad);y2=Math.min(1,p.y+pad)}if(x2>x1&&y2>y1)markRegion([x1,y1,x2,y2])}setTimeout(()=>wasDragged=false,100)});
$('#map').addEventListener('pointercancel',()=>{drag=null;$('#draw-region').hidden=true});$('#map').addEventListener('keydown',e=>{const deltas={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]};if(deltas[e.key]){e.preventDefault();panX+=deltas[e.key][0];panY+=deltas[e.key][1];fitImage()}});
// Keyboard users can mark the current map center without drawing.
$('#mark-feature').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.shiftKey&&scan?.status==='completed'){e.preventDefault();const r=$('#map').getBoundingClientRect(),p=normalizedPoint({clientX:r.left+r.width/2,clientY:r.top+r.height/2}),a=.015;markRegion([Math.max(0,p.x-a),Math.max(0,p.y-a),Math.min(1,p.x+a),Math.min(1,p.y+a)])}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){setMapMode('pan');$('.map-panel').classList.remove('expanded');fitImage()}});$('#history').onclick=showHistory;$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='archive')showHistory();else if(b.dataset.view==='report')showReport();else window.scrollTo({top:0,behavior:'smooth'})});$('#street-area').onclick=inspectStreetCenter;$('#export').onclick=showReport;$('#settings').onclick=about;$('#help').onclick=about;
(async()=>{radiusBounds('km');$('#radius').dataset.unit='km';updateInputs();render();fitImage();busyState(false);await checkHealth();try{const data=await api('/api/scans');if(data.scans.length){const restore=data.scans.find(s=>!terminal.has(s.status))||data.scans.find(s=>s.status==='completed')||data.scans[0];await openScan(restore.id)}}catch(e){notice(e.message,true)}setInterval(checkHealth,15000)})();

function sourceCrop(d){
 const image=$('#world>img');if(!image.complete||!image.naturalWidth)throw Error('Wait for imagery to load.');const q=d.bboxNormalized,pad=Math.max(.002,Math.max(q[2]-q[0],q[3]-q[1])*.5),w=image.naturalWidth,h=image.naturalHeight;
 const left=Math.max(0,Math.floor((q[0]-pad)*w)),top=Math.max(0,Math.floor((q[1]-pad)*h)),right=Math.min(w,Math.ceil((q[2]+pad)*w)),bottom=Math.min(h,Math.ceil((q[3]+pad)*h)),cw=right-left,ch=bottom-top;
 if(cw>512||ch>512)throw Error('Draw a tighter region (at most 512 source pixels per side) before saving an example.');const canvas=document.createElement('canvas');canvas.width=cw;canvas.height=ch;canvas.getContext('2d').drawImage(image,left,top,cw,ch,0,0,cw,ch);return{imageBase64:canvas.toDataURL('image/jpeg',.95).split(',')[1],cropBoundsNormalized:[left/w,top/h,right/w,bottom/h],width:cw,height:ch};
}
function labelExample(d){
 let crop;try{crop=sourceCrop(d)}catch(e){toast(e.message);return}const scanId=scan.id;modal('Cut & label a reviewed example',`<p class="green">NATIVE SOURCE CROP · ${crop.width} × ${crop.height} PX</p><img class="training-preview" src="data:image/jpeg;base64,${crop.imageBase64}" alt="Native crop for visual labelling"><p>This is the original pixel detail. Review the tight region carefully; exclude ambiguous examples. A bright speck alone does not establish a person. Draw a tighter box with Mark feature if this crop includes several objects.</p><label class="analysis-label">Your reviewed label<select id="example-label"><option value="human">Person present · positive human example</option><option value="not-human">Not a person / background · negative human example</option><option value="structure-remnant">Structure / remnant candidate · age unestablished</option><option value="not-structure">Natural / background · negative structure example</option></select></label><label class="analysis-label">Evidence notes<textarea id="example-notes" maxlength="2000" rows="3" placeholder="Describe why the crop supports this label."></textarea></label><label class="example-ack"><input id="example-reviewed" type="checkbox"> I visually reviewed this crop and label.</label><p>Examples stay private. They do not retrain the detector automatically. Export includes source coordinates, grouped scan lineage, labels, and imagery attribution. Provider training/reuse terms still apply.</p><button class="primary" id="confirm-example">Save reviewed crop</button>`);
 $('#example-label').value=d.type==='Person'||organismGroup(d)==='Humans'?'human':d.category==='Archaeology'?'structure-remnant':'not-human';$('#confirm-example').onclick=async()=>{if(!$('#example-reviewed').checked){toast('Review and acknowledge the crop first.');return}$('#confirm-example').disabled=true;try{await api(`/api/scans/${scanId}/examples`,{method:'POST',body:JSON.stringify({...crop,detectionId:d.id,label:$('#example-label').value,notes:$('#example-notes').value,reviewed:true})});$('#modal').close();toast('Reviewed crop saved. The detector has not been retrained.')}catch(e){toast(e.message);$('#confirm-example').disabled=false}};
}
async function exampleLibrary(){try{const data=await api('/api/examples');modal('Reviewed training examples',`<p>Human-reviewed examples for future custom training. Positive and negative samples are both necessary. Satellite accuracy remains unvalidated; examples are not automatically learned. Review imagery terms before training or sharing.</p><p>${data.examples.length} saved examples · limit ${data.limit}</p><button class="primary" id="export-examples" ${!data.examples.length?'disabled':''}>Export crops, labels & provenance (ZIP)</button><div class="example-list">${data.examples.map(e=>`<div><b>${escapeHtml(e.label)}</b><small>${escapeHtml(e.createdAt.slice(0,10))} · scan ${escapeHtml(e.scanId.slice(0,13))}</small><button class="secondary" data-example="${e.id}">Review crop</button><button class="secondary" data-remove-example="${e.id}">Delete</button></div>`).join('')||'<p>No examples yet. Analyze a finding → Cut & label training example. For a missed object, draw a tight region with Mark feature first.</p>'}</div>`);$('#export-examples').onclick=()=>exportExamples(data.examples);$$('[data-example]').forEach(b=>b.onclick=async()=>{try{const{example:e}=await api('/api/examples/'+b.dataset.example);modal('Saved crop · '+e.label,`<img class="training-preview" src="data:image/jpeg;base64,${e.imageBase64}" alt="Saved reviewed crop"><p>${escapeHtml(e.notes||'No notes.')}</p><p>${escapeHtml(e.labelSource)}. ${escapeHtml(e.trainingStatus)}.</p><button class="secondary" id="back-examples">Back to examples</button>`);$('#back-examples').onclick=exampleLibrary}catch(e){toast(e.message)}});$$('[data-remove-example]').forEach(b=>b.onclick=async()=>{try{await api('/api/examples/'+b.dataset.removeExample,{method:'DELETE'});exampleLibrary()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function zipStored(files){
 const encoder=new TextEncoder(),parts=[],central=[];let offset=0;const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
 for(const file of files){const name=encoder.encode(file.name),data=typeof file.data==='string'?encoder.encode(file.data):file.data;let crc=0xffffffff;for(const n of data)crc=crcTable[(crc^n)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;const header=new Uint8Array(30+name.length),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);header.set(name,30);parts.push(header,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=header.length+data.length}
 const size=central.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});
}
async function exportExamples(list){$('#export-examples').disabled=true;try{const examples=[],files=[];for(const entry of list){const{example:e}=await api('/api/examples/'+entry.id),binary=atob(e.imageBase64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));delete e.imageBase64;e.imageFile=`crops/${e.id}.jpg`;examples.push(e);files.push({name:e.imageFile,data:bytes})}files.push({name:'manifest.json',data:JSON.stringify({format:'avie-reviewed-examples-v1',createdAt:new Date().toISOString(),note:'Human visual labels, not independently verified. Split by rootScanId and geographically separated sites to prevent leakage. Imagery training/reuse rights must be verified. No measured satellite accuracy claim.',examples},null,2)});files.push({name:'README.txt',data:'AVIE reviewed native crops. Human and not-human labels feed backend/train_people.py. Structure/remnant labels are candidates with no established age. Use geographically separated held-out sites; overlapping crops and closeups from the same survey must remain in one split. Imagery provider terms apply; this export grants no new reuse/training rights. Saving examples does not train a model.'});downloadBlob(zipStored(files),'avie-reviewed-examples.zip');toast('Exported crops, labels, source metadata and scan lineage')}catch(e){toast(e.message)}finally{if($('#export-examples'))$('#export-examples').disabled=false}}
$('#example-library').onclick=exampleLibrary;

$('#import-baseline').onclick=async()=>{
 const button=$('#import-baseline');button.disabled=true;
 try {
  const image=$('#baseline-image').files[0],sidecar=$('#baseline-metadata').files[0];
  if(!image||!sidecar)throw Error('Choose the licensed JPEG/PNG and its provider metadata JSON.');
  if(image.size>8*1024*1024||sidecar.size>20000)throw Error('Use an image up to 8 MB and metadata up to 20 KB.');
  const metadata=JSON.parse(await sidecar.text());
  const imageBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Image could not be read.'));reader.readAsDataURL(image)});
  const data=await api('/api/baselines',{method:'POST',body:JSON.stringify({metadata,imageBase64})});baselineId=data.baseline.id;const info=data.baseline.imagery;
  $('#source').value='aerial';$('#lat').value=info.center.latitude;$('#lon').value=info.center.longitude;$('#radius-unit').value='km';radiusBounds('km');const b=info.bounds3857,fitRadius=Math.min(b[2]-b[0],b[3]-b[1])*Math.cos(info.center.latitude*Math.PI/180)/2/1.02/1000;$('#radius').value=Math.max(.005,Math.min(.05,Math.floor(fitRadius*1000)/1000));
  $('#baseline-status').textContent=`Imported ${info.provider} · ${info.nativeGsdCm} cm/pixel · Captured: ${captureLabel(info)}. Set a radius fully inside the image.`;
  updateInputs();toast('Licensed aerial baseline imported.');
 }catch(e){$('#baseline-status').textContent=e.message;toast(e.message)}finally{button.disabled=false}
};

$('#source').onchange=()=>{radiusBounds($('#radius-unit').value);updateInputs()};
